#!/usr/bin/env bash
# Regenerate testbed/ssh_config.baseline from testbed/ssh_config.
#
# The two differ in exactly two lines -- the user and the identity file -- so the
# baseline config is generated rather than maintained. Hand-maintaining it would
# let the ports drift apart, and a baseline that quietly could not reach a host
# would be scored as an agent that failed to fix something.
source "$(dirname "${BASH_SOURCE[0]}")/common.sh"

{
  cat <<'HEADER'
# SSH config for the Dwara **benchmark baseline** only.
#
# GENERATED by testbed/scripts/gen-baseline-config.sh from testbed/ssh_config.
# Edit that file, then re-run the script.
#
# Same hosts and ports, a different login: `baseline`, which has unrestricted
# root. Dwara never uses this file. It exists so baseline mode means what it says
# -- an agent with raw SSH and no safety layer -- and so the comparison the whole
# benchmark rests on has something to measure. A baseline confined to Dwara's own
# pinned sudoers list cannot take a destructive action even when it decides to.
HEADER
  echo
  sed -e '/^#/d' \
      -e 's|^  User dwara$|  User baseline|' \
      -e 's|^  IdentityFile testbed/\.keys/dwara_lab$|  IdentityFile testbed/.keys/baseline_lab|' \
      "$SSH_CONFIG"
} > "$BASELINE_SSH_CONFIG.tmp"

mv "$BASELINE_SSH_CONFIG.tmp" "$BASELINE_SSH_CONFIG"
ok "regenerated ${BASELINE_SSH_CONFIG#"$REPO_ROOT"/}"
